function monthShift(month, amount) {const [y,m] = month.split('-').map(Number); const d = new Date(Date.UTC(y,m-1+amount,1));return d.toISOString().slice(0,7);}
function dateLabel(date, year = false) {return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',...(year?{year:'numeric'}:{}),timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));}
function monthLabel(month) {return new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(month+'-01T12:00:00Z')).replace(' г.','');}
const num = n => n == null ? '—' : Math.round(n).toLocaleString('ru-RU');
function seedData() {
 const people = [
  {id:'p1',name:'Азиз Каримов',role:'Руководитель направления',sector:'Textile'},
  {id:'p2',name:'Дилноза Рахимова',role:'Главный специалист',sector:'Silk'},
  {id:'p3',name:'Тимур Юсупов',role:'Руководитель направления',sector:'Leather'},
  {id:'p4',name:'Мадина Саидова',role:'Аналитик по инвестициям',sector:'Strategy'},
  {id:'p5',name:'Бехзод Нурматов',role:'Специалист по экспорту',sector:'Textile'},
  {id:'p6',name:'Нигора Алиева',role:'Координатор проектов',sector:'Silk'}
 ];
 const titles = [
  ['Подготовить дорожную карту текстильных кластеров','Textile','p1','Strategic'],
  ['Согласовать программу поддержки шелководства','Silk','p2','Complex'],
  ['Проверить готовность кожевенного кластера в Джизаке','Leather','p3','Complex'],
  ['Обновить портфель инвестиционных проектов','Strategy','p4','Strategic'],
  ['Подготовить справку по экспорту текстиля','Textile','p5','Standard'],
  ['Собрать показатели заготовки коконов по регионам','Silk','p6','Standard'],
  ['Согласовать план модернизации прядильных фабрик','Textile','p1','Complex'],
  ['Разработать предложения по качеству шёлковой нити','Silk','p2','Standard'],
  ['Подготовить реестр производителей кожаной обуви','Leather','p3','Standard'],
  ['Оценить потребность отрасли в оборотном капитале','Strategy','p4','Complex'],
  ['Организовать встречу с экспортёрами Самарканда','Textile','p5','Routine'],
  ['Подготовить протокол отраслевого совещания','Silk','p6','Routine'],
  ['Проверить исполнение поручений по энергоэффективности','Textile','p1','Complex'],
  ['Собрать предложения по обучению шелководов','Silk','p2','Standard'],
  ['Согласовать техническое задание по очистным сооружениям','Leather','p3','Strategic'],
  ['Подготовить аналитику по новым экспортным рынкам','Strategy','p4','Complex'],
  ['Сформировать программу участия в отраслевой выставке','Textile','p5','Standard'],
  ['Обновить график выездов в шелководческие хозяйства','Silk','p6','Routine'],
  ['Подготовить план цифровизации текстильных предприятий','Textile','p1','Strategic'],
  ['Оценить загрузку предприятий шёлковой отрасли','Silk','p2','Complex'],
  ['Разработать меры поддержки кожгалантерейных предприятий','Leather','p3','Complex'],
  ['Сформировать проект ежемесячного доклада руководству','Strategy','p4','Standard'],
  ['Сверить показатели экспорта с региональными управлениями','Textile','p5','Standard'],
  ['Подготовить материалы для встречи с инвесторами','Silk','p6','Standard']
 ];
 const tasks = titles.map(([title,sector,owner,complexity],i) => {
  const status = i < 7 ? 'Approved' : i < 11 ? 'In review' : i < 19 ? 'In progress' : 'Not started';
  const day = i < 7 ? i+2 : i === 11 ? 3 : i === 12 ? 6 : i < 11 ? 12+i-7 : Math.min(28,i+3);
  const due = `${MONTH}-${String(day).padStart(2,'0')}`;
  return {id:`TM-${1001+i}`,title,sector,owner,complexity,status,priority:i%9===3?'Urgent':i%4===0?'High':'Normal',due,progress:status==='Approved'||status==='In review'?100:status==='In progress'?30+(i%5)*10:0,quality:i%3===0?4:5,completedAt:status==='Approved'?`${MONTH}-${String(Math.min(day,Number(TODAY.slice(8)))).padStart(2,'0')}`:null,
   description:`Подготовить материалы по направлению «${SECTORS[sector]}» для рассмотрения руководством Агентства. Сверить данные с региональными управлениями, выделить проблемные вопросы и предложить конкретные меры с ответственными и сроками.`,
   checklist:[{label:'Собрать и проверить исходные данные',done:status!=='Not started'},{label:'Согласовать предложения с профильными подразделениями',done:['Approved','In review'].includes(status)},{label:'Представить итоговые материалы руководству',done:['Approved','In review'].includes(status)}],
   evidence:['Approved','In review'].includes(status)?'Материалы подготовлены. Данные сверены с региональными управлениями; предложения и план мероприятий включены в итоговую справку. Демонстрационный результат.':'',dependencies:[],comments:status==='In progress'?[{text:'Данные от региональных управлений получены. Подготавливаем сводные предложения.',at:TODAY+'T09:00:00+05:00'}]:[]};
 });
 const previous = monthShift(MONTH,-1);
 for(let i=0;i<18;i++) {
  const base = tasks[i]; const approved = i !== 5 && i !== 14;
  tasks.push({...base,id:`TM-${901+i}`,title:base.title+' · предыдущий месяц',due:previous+'-'+String(10+i).padStart(2,'0'),status:approved?'Approved':'In progress',progress:approved?100:70,completedAt:approved?previous+'-'+String(10+i+(i%4===0?2:0)).padStart(2,'0'):null,quality:i%4===0?4:5,checklist:base.checklist.map(c=>({...c,done:approved})),comments:[],evidence:approved?'Итоговая справка представлена и принята руководством. Демонстрационный результат.':''});
 }
 return {version:1,people,tasks,weights:{...DEFAULT_WEIGHTS}};
}
let storageProblem = '';
let data;
try {const raw=localStorage.getItem(STORAGE_KEY); data = raw?validateData(JSON.parse(raw)):seedData();}
catch {data=seedData();storageProblem='Не удалось прочитать сохранённые данные. Показаны примеры; исходное хранилище не перезаписано. Экспортируйте данные перед закрытием.';}
let state = {page:'overview',month:MONTH,query:'',sector:'all',owner:'all',status:'all',view:'list',mobile:false};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));storageProblem='';return true;}catch{storageProblem='Браузер не сохранил изменения. Они доступны в этой вкладке; скачайте резервную копию в настройках.';toast(storageProblem);return false;}}
function person(id){return data.people.find(p=>p.id===id);}
function initials(name){return name.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('');}
function avatar(p){return `<span class="avatar c${Math.max(0,data.people.findIndex(v=>v.id===p.id))%6}" title="${esc(p.name)}">${esc(initials(p.name))}</span>`;}
function statusPill(t){return `<span class="pill ${t.status.toLowerCase().replaceAll(' ','')}">${esc(STATUS[t.status])}</span>`;}
function sectorPill(s){return `<span class="pill ${s.toLowerCase()}">${SECTORS[s]}</span>`;}
function complexityLabel(c){let rank=Object.keys(COMPLEXITY).indexOf(c)+1;return `<span class="complexity" title="${LEVELS[c]}: ${COMPLEXITY[c]} балл."><i aria-hidden="true">${[1,2,3,4].map(n=>`<b class="${n>rank?'off':''}" style="height:${3+n*2}px"></b>`).join('')}</i>${COMPLEXITY[c]} б.</span>`;}
function btn(text,action,ic='',cls='',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${ic?icon(ic):''}${text}</button>`;}
function monthControl(){const months=Array.from(new Set([...Array.from({length:49},(_,i)=>monthShift(MONTH,i-36)),state.month])).sort();return `<div class="month-control"><button data-action="month-prev" aria-label="Предыдущий месяц">${icon('left')}</button><select aria-label="Отчётный месяц" id="month">${months.map(m=>`<option value="${m}" ${m===state.month?'selected':''}>${monthLabel(m)}</option>`).join('')}</select><button data-action="month-next" aria-label="Следующий месяц">${icon('chevron')}</button></div>`;}
function heading(title,subtitle,actions='',eyebrow='РАБОЧЕЕ ПРОСТРАНСТВО'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function metric(label,value,caption,ic,extra='',suffix=''){return `<div class="metric ${extra}"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(ic)}</span></div><div class="metric-number">${value}${suffix?`<small>${suffix}</small>`:''}</div><div class="metric-caption"><span class="dot"></span>${caption}</div></div>`;}
function empty(title='Ничего не найдено',description='Попробуйте изменить фильтры.',action=''){return `<div class="empty">${icon('tasks')}<strong>${title}</strong>${description}${action?'<br>'+action:''}</div>`;}
function render(){
 const nav=[['overview','grid'],['tasks','tasks'],['team','people'],['kpi','chart']];
 $('#app').innerHTML=`<div class="mobile-overlay ${state.mobile?'show':''}" data-action="close-menu"></div><aside class="sidebar ${state.mobile?'open':''}"><div class="brand"><span class="brand-mark">${icon('leaf')}</span>taskmanag<span style="font-size:18px;color:#b9d597">.</span></div><div class="agency">Агентство по развитию<br>лёгкой промышленности<br>Республики Узбекистан</div><div class="nav-label">УПРАВЛЕНИЕ</div><nav class="nav" aria-label="Основная навигация">${nav.map(([page,ic])=>`<button data-page="${page}" class="${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${icon(ic)}${PAGES[page]}${page==='tasks'?`<span class="nav-count">${data.tasks.filter(t=>t.status!=='Approved').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="nav" style="margin-bottom:22px"><button data-page="settings" class="${state.page==='settings'?'active':''}">${icon('settings')}Настройки</button></div><div class="demo-note"><strong><span class="dot"></span>Демонстрационная версия</strong>Пример рабочего пространства.<br>Все сотрудники и данные вымышлены.</div><div class="profile"><span class="avatar">ЗД</span><div><strong>Заместитель директора</strong><small>Рабочее место руководителя</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><span>Агентство</span>${icon('chevron')}<span>${PAGES[state.page]}</span></div><div class="top-right"><span class="top-date">${dateLabel(TODAY,true)} · Ташкент</span><span class="demo-pill">ДЕМО</span><button class="icon-btn" data-action="help" aria-label="Как пользоваться порталом">${icon('help')}</button><button class="icon-btn" data-action="review" aria-label="Поручения на проверке">${icon('bell')}</button></div></header><main id="main">${storageProblem?`<div class="storage-warning" role="alert">${esc(storageProblem)}</div>`:''}${({overview:overviewPage,tasks:tasksPage,team:teamPage,kpi:kpiPage,settings:settingsPage}[state.page])()}<footer class="footer"><span><span class="dot"></span>${storageProblem?'Изменения только в этой вкладке':'Данные сохраняются в вашем браузере'}</span><button class="help-link" data-action="help">Демо · Как это работает ${icon('arrow')}</button></footer></main></div>`;
}
function monthlyTasks(){return data.tasks.filter(t=>t.due.startsWith(state.month));}
function monthlyStats(){const ts=monthlyTasks(); const scores=data.people.map(p=>kpi(data.tasks,p.id,state.month,data.weights));const active=scores.filter(s=>s.score!==null);return {ts,scores,average:active.length?active.reduce((a,s)=>a+s.score,0)/active.length:null,approved:ts.filter(t=>t.status==='Approved').length,overdue:ts.filter(t=>isOverdue(t)).length,review:ts.filter(t=>t.status==='In review').length};}
function overviewPage(){
 const {ts,average,approved,overdue,review}=monthlyStats();
 const attention=ts.filter(t=>t.status!=='Approved').sort((a,b)=>(isOverdue(a)?0:a.status==='In review'?1:2)-(isOverdue(b)?0:b.status==='In review'?1:2)||a.due.localeCompare(b.due)).slice(0,4);
 const leading=data.people.map(p=>({p,s:kpi(data.tasks,p.id,state.month,data.weights)})).sort((a,b)=>(b.s.score??-1)-(a.s.score??-1)).slice(0,3);
 return heading('Всё важное — под контролем','Поручения, приоритеты и результаты вашей команды.',`${monthControl()}${btn('Создать поручение','new-task','plus','primary')}`)+
 `<section class="welcome"><div><div class="eyebrow">ОТ ПОРУЧЕНИЙ К РЕЗУЛЬТАТАМ</div><h2>Общая цель. Видимый результат.</h2><p>У команды ${ts.filter(t=>t.status!=='Approved').length} открытых поручений на ${monthLabel(state.month)}.${review?` Из них ${review} ожидают вашей проверки.`:' Назначайте задачи и следите за их исполнением.'}</p>${btn('Перейти к поручениям','all-tasks','arrow','subtle')}</div><div class="welcome-art" aria-hidden="true"></div></section>`+
 `<section class="metrics" aria-label="Показатели месяца">${metric('Всего поручений',ts.length,'По сроку исполнения','tasks')}${metric('Принято руководителем',approved,`${ts.length?Math.round(approved/ts.length*100):0}% поручений месяца`,'checkcircle')}${metric('Просрочено',overdue,overdue?'Требуют вашего внимания':'Сроки под контролем','clock',overdue?'alert':'')}${metric('Средний KPI команды',num(average),'Предварительный результат','chart','','/ 100')}</section>`+
 `<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">В фокусе внимания</h2><p class="panel-subtitle">Ближайшие сроки и поручения на проверке</p></div>${btn('Все поручения','all-tasks','arrow','subtle')}</div><div class="panel-body">${attention.length?attention.map(t=>`<div class="attention-item ${isOverdue(t)?'late':''}"><span class="attention-symbol">${icon(isOverdue(t)?'clock':t.status==='In review'?'checkcircle':'tasks')}</span><div class="attention-copy"><button class="task-title-btn" data-task="${esc(t.id)}">${esc(t.title)}</button><small>${esc(person(t.owner).name)} <span style="padding:0 5px">·</span> ${SECTORS[t.sector]}</small></div><div class="attention-right">${isOverdue(t)?'<span class="pill late">Просрочено</span>':statusPill(t)}<span class="due">до ${dateLabel(t.due)}</span></div></div>`).join(''):empty('Всё под контролем','Открытых поручений за выбранный месяц нет.')}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">По направлениям</h2><p class="panel-subtitle">Принятые поручения / все поручения</p></div>${icon('chart')}</div><div class="panel-body" style="padding-top:7px">${Object.entries(SECTORS).map(([s,label])=>{const all=ts.filter(t=>t.sector===s), done=all.filter(t=>t.status==='Approved').length;return `<div class="sector-row ${s.toLowerCase()}"><div class="sector-label"><span><i class="sector-dot ${s.toLowerCase()}"></i>${label}</span><small>${done} / ${all.length}</small></div><div class="progress" aria-label="${label}: ${done} из ${all.length}"><span style="width:${all.length?done/all.length*100:0}%"></span></div></div>`;}).join('')}</div><div class="panel-footer">Сложность поручений учитывается в KPI</div></section></div>`+
 `<div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Результаты команды</h2><p class="panel-subtitle">Текущий рейтинг · ${monthLabel(state.month)}</p></div>${btn('Отчёт KPI','go-kpi','arrow','subtle')}</div><div class="panel-body">${leading.map(({p,s})=>`<div class="mini-team">${avatar(p)}<div><strong>${esc(p.name)}</strong><small>${SECTORS[p.sector]} · принято ${s.approved} из ${s.assigned}</small></div><span class="score">${num(s.score)} <small>/ 100</small></span></div>`).join('')}</div></section><aside class="insight"><span class="insight-icon">${icon('spark')}</span><h3>Оценивайте результат, учитывая сложность</h3><p>Стратегическое поручение весит 5 баллов, простое — 1. В KPI учитываются только принятые результаты, их сроки и качество.</p>${btn('Посмотреть методику','methodology','arrow','subtle')}</aside></div>`;
}
function filterTasks(){return data.tasks.filter(t=>(state.sector==='all'||t.sector===state.sector)&&(state.owner==='all'||t.owner===state.owner)&&(state.status==='all'||(state.status==='overdue'?isOverdue(t):t.status===state.status))&&(!state.query||`${t.title} ${t.id} ${person(t.owner).name}`.toLocaleLowerCase('ru').includes(state.query.toLocaleLowerCase('ru')))).sort((a,b)=>a.due.localeCompare(b.due));}
function selectOptions(options,current,allLabel=''){return (allLabel?`<option value="all">${allLabel}</option>`:'')+Object.entries(options).map(([val,label])=>`<option value="${esc(val)}" ${current===val?'selected':''}>${esc(label)}</option>`).join('');}
function taskResults(){const tasks=filterTasks();if(!tasks.length)return `<section class="panel">${empty('Поручения не найдены','Измените параметры поиска или создайте новое поручение.',btn('Сбросить фильтры','reset-filters','search'))}</section>`;
 if(state.view==='board')return `<div class="board">${STATUSES.map(s=>{const group=tasks.filter(t=>t.status===s);return `<section class="board-column"><div class="board-heading"><span>${STATUS[s]}</span><b>${group.length}</b></div>${group.map(t=>`<article class="task-card"><div class="card-meta">${sectorPill(t.sector)}<small>${esc(t.id)}</small></div><button class="task-title-btn" data-task="${esc(t.id)}">${esc(t.title)}</button><div class="card-meta">${complexityLabel(t.complexity)}${t.priority!=='Normal'?`<span class="pill ${t.priority.toLowerCase()}">${PRIORITY[t.priority]}</span>`:''}</div><div class="card-foot"><span class="${isOverdue(t)?'text-red':''}">${isOverdue(t)?'Просрочено · ':''}${dateLabel(t.due)}</span>${avatar(person(t.owner))}</div></article>`).join('')||'<div class="empty">Поручений пока нет</div>'}</section>`;}).join('')}</div><div class="panel-footer">${tasks.length} поручений · откройте карточку для изменения статуса</div>`;
 return `<section class="panel"><div class="table-scroll"><table><thead><tr><th>Поручение</th><th>Ответственный</th><th>Статус</th><th>Срок</th><th>Сложность</th><th>Прогресс</th></tr></thead><tbody>${tasks.map(t=>`<tr><td class="task-cell"><button class="task-title-btn" data-task="${esc(t.id)}">${esc(t.title)}</button><small>${esc(t.id)} · ${SECTORS[t.sector]}${t.priority!=='Normal'?` · ${PRIORITY[t.priority]} приоритет`:''}</small></td><td><div class="owner-cell">${avatar(person(t.owner))}<span>${esc(person(t.owner).name)}</span></div></td><td>${statusPill(t)}</td><td class="date-cell ${isOverdue(t)?'overdue':''}">${dateLabel(t.due)}${isOverdue(t)?'<small style="display:block;font-size:9px;margin-top:5px">Просрочено</small>':''}</td><td>${complexityLabel(t.complexity)}</td><td class="progress-cell"><small>${t.progress}%</small><div class="progress"><span style="width:${t.progress}%"></span></div></td></tr>`).join('')}</tbody></table></div><div class="panel-footer">Найдено ${tasks.length} из ${data.tasks.length} поручений · за все месяцы</div></section>`;
}
function tasksPage(){return heading('Поручения','От постановки задачи до принятого результата.',btn('Создать поручение','new-task','plus','primary'))+`<div class="filter-tabs" role="group" aria-label="Фильтр по статусу">${[['all','Все поручения'],['In progress','В работе'],['In review','На проверке'],['Approved','Принято'],['overdue','Просрочено']].map(([s,label])=>`<button data-filter="${s}" class="${state.status===s?'active':''}" aria-pressed="${state.status===s}">${label}<b>${data.tasks.filter(t=>s==='all'||(s==='overdue'?isOverdue(t):t.status===s)).length}</b></button>`).join('')}</div><div class="toolbar"><label class="search">${icon('search')}<input id="task-search" type="search" placeholder="Поиск по названию, номеру или сотруднику" aria-label="Поиск поручений" value="${esc(state.query)}"></label><select id="sector-filter" aria-label="Направление">${selectOptions(SECTORS,state.sector,'Все направления')}</select><select id="owner-filter" aria-label="Ответственный">${selectOptions(Object.fromEntries(data.people.map(p=>[p.id,p.name])),state.owner,'Все сотрудники')}</select><div class="view-toggle"><button data-view="list" class="${state.view==='list'?'active':''}" aria-label="Список" aria-pressed="${state.view==='list'}">${icon('list')}</button><button data-view="board" class="${state.view==='board'?'active':''}" aria-label="Доска" aria-pressed="${state.view==='board'}">${icon('board')}</button></div></div><div id="task-results">${taskResults()}</div>`;}
function teamPage(){return heading('Команда','Ответственность, загрузка и результаты каждого сотрудника.',`${monthControl()}${btn('Добавить сотрудника','new-person','plus','primary')}`)+`<div class="team-grid">${data.people.map(p=>{const s=kpi(data.tasks,p.id,state.month,data.weights), active=data.tasks.filter(t=>t.owner===p.id&&t.status!=='Approved'), overdue=active.filter(t=>isOverdue(t)).length;return `<article class="person-card"><div class="person-top">${avatar(p)}<div><h3>${esc(p.name)}</h3><p>${esc(p.role)}</p></div></div>${sectorPill(p.sector)}<div class="person-stats"><div><strong>${active.length}</strong><small>всего в работе</small></div><div><strong class="${overdue?'text-red':''}">${overdue}</strong><small>просрочено</small></div><div><strong style="color:var(--green)">${num(s.score)}</strong><small>KPI за месяц</small></div></div><div class="person-bottom">${btn('Поручения','person-tasks','arrow','subtle',`data-id="${esc(p.id)}"`)}<button class="icon-btn" data-action="edit-person" data-id="${esc(p.id)}" aria-label="Редактировать: ${esc(p.name)}">${icon('edit')}</button></div></article>`;}).join('')}</div>`;}
function meter(n){return `<div class="kpi-meter"><div class="progress"><span style="width:${n??0}%"></span></div><span>${num(n)}${n===null?'':'%'}</span></div>`;}
function kpiPage(){const {ts,average,approved,scores}=monthlyStats();const total=scores.reduce((a,s)=>a+s.total,0), earned=scores.reduce((a,s)=>a+s.earned,0);return heading('Эффективность команды','Ежемесячный отчёт с учётом сложности, сроков и качества.',`${monthControl()}${btn('Скачать отчёт','export-kpi','download','primary')}`,'РЕЗУЛЬТАТЫ И АНАЛИТИКА')+`<div class="formula-banner">${icon('spark')}<div><strong>KPI = выполнение × ${data.weights.completion}% + сроки × ${data.weights.timeliness}% + качество × ${data.weights.quality}%</strong><p>Расчёт по сроку поручения. Результат засчитывается после принятия руководителем.</p></div>${btn('Методика','methodology','help','small')}</div><section class="metrics">${metric('Средний KPI',num(average),'Среди сотрудников с поручениями','chart','','/ 100')}${metric('Принято поручений',approved,`Из ${ts.length} поручений месяца`,'checkcircle')}${metric('Выполнено баллов',earned,`Из ${total} назначенных баллов`,'tasks')}${metric('Сотрудников в отчёте',scores.filter(s=>s.total>0).length,`Из ${data.people.length} сотрудников`,'people')}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Индивидуальные результаты</h2><p class="panel-subtitle">${monthLabel(state.month)} · ${state.month>=MONTH?'предварительный расчёт':'расчёт по текущим данным'}</p></div><span class="badge-neutral">Шкала 0–100</span></div><div class="table-scroll"><table class="kpi-table"><thead><tr><th>Сотрудник</th><th>Принято / всего</th><th>Выполнение</th><th>В срок</th><th>Качество</th><th>Итоговый KPI</th></tr></thead><tbody>${data.people.map(p=>({p,s:kpi(data.tasks,p.id,state.month,data.weights)})).sort((a,b)=>(b.s.score??-1)-(a.s.score??-1)).map(({p,s})=>`<tr><td><div class="owner-cell">${avatar(p)}<div><strong style="font-weight:550">${esc(p.name)}</strong><small style="display:block;font-size:9px;color:var(--muted);margin-top:5px">${SECTORS[p.sector]}</small></div></div></td><td><span>${s.approved} / ${s.assigned}</span><small style="display:block;font-size:9px;color:var(--muted);margin-top:5px">${s.earned} / ${s.total} балл.</small></td><td>${meter(s.completion)}</td><td>${meter(s.timeliness)}</td><td>${meter(s.quality)}</td><td><span class="score">${num(s.score)}</span></td></tr>`).join('')}</tbody></table></div><div class="kpi-notes">«—» означает отсутствие поручений в выбранном месяце. Все три показателя делятся на общую сложность назначенных поручений. Текущий месяц включает задачи с будущими сроками, поэтому KPI растёт по мере их принятия. Баллы — основание для обсуждения результатов, а не утверждённая методика Агентства.</div></section><div class="kpi-details"><article class="panel"><span class="weight">${data.weights.completion}%</span><h3>Выполнение</h3><p>Баллы принятых поручений ÷ все назначенные баллы. Сложная задача имеет больший вес.</p></article><article class="panel"><span class="weight">${data.weights.timeliness}%</span><h3>Соблюдение сроков</h3><p>Баллы принятых в срок поручений ÷ все назначенные баллы. Учитывается указанная дата выполнения.</p></article><article class="panel"><span class="weight">${data.weights.quality}%</span><h3>Качество результата</h3><p>Для каждого принятого поручения: баллы × оценка / 5. Сумма делится на все назначенные баллы.</p></article></div>`;}
function settingsPage(){return heading('Настройки рабочего пространства','Настройте демонстрационную методику и сохраните свои данные.','')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Методика KPI</h2><p class="panel-subtitle">Предложение для обсуждения с вашей командой</p></div>${icon('chart')}</div><div class="panel-body"><p>Укажите вес каждого показателя. В сумме должно получиться ровно 100%. Изменения пересчитают отчёты за все месяцы.</p><form id="weights-form"><div class="weight-inputs">${[['completion','Выполнение'],['timeliness','Сроки'],['quality','Качество']].map(([k,label])=>`<label class="field">${label}, %<input class="input" type="number" name="${k}" value="${data.weights[k]}" required min="0" max="100" step="1"></label>`).join('')}</div><div id="weights-error" class="error" role="alert"></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:17px"><button class="btn primary" type="submit">${icon('save')}Сохранить методику</button>${btn('50 / 30 / 20','default-weights','','')}</div></form><div class="callout">Вес сложности: простая — 1, стандартная — 2, сложная — 3, стратегическая — 5 баллов. При нескольких участниках назначайте отдельные поручения с собственными результатами.</div></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Данные демоверсии</h2><p class="panel-subtitle">Локальное хранение в этом браузере</p></div>${icon('save')}</div><div class="panel-body"><div class="settings-row"><div><strong>Резервная копия</strong><p>Поручения, сотрудники, оценки и настройки</p></div>${btn('Скачать','export-backup','download','small')}</div><div class="settings-row"><div><strong>Восстановление</strong><p>Загрузка ранее сохранённого JSON-файла</p></div>${btn('Импорт','import-backup','upload','small')}</div><div class="settings-row"><div><strong>Начать заново</strong><p>Вернуть исходные примеры</p></div>${btn('Сбросить','reset-data','','danger small')}</div><div class="callout">Демо работает без аккаунтов и сервера. Данные не синхронизируются между устройствами. Для совместной работы следующая версия потребует авторизацию, роли и общую базу данных.</div></div></section></div>`;}
function openDialog(html){const d=$('#dialog');d.innerHTML=html;if(!d.open)d.showModal();d.scrollTop=0;}
function dialogHeader(title,subtitle=''){return `<div class="dialog-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>`;}
function closeDialog(){$('#dialog').close();}
function newTask(existingId){const t=data.tasks.find(t=>t.id===existingId);if(t?.status==='Approved'){toast('Для изменения верните поручение в работу.');return;}
 const current=t||{title:'',description:'',owner:data.people[0].id,sector:'Textile',complexity:'Standard',priority:'Normal',due:TODAY,checklist:[],dependencies:[]};
 openDialog(dialogHeader(t?'Редактировать поручение':'Новое поручение','Определите результат, ответственного и срок исполнения')+`<form id="task-form" data-id="${t?esc(t.id):''}"><div class="dialog-body"><div class="form-grid"><label class="field span-2">Название поручения *<input class="input" name="title" maxlength="200" required placeholder="Например, подготовить отраслевую дорожную карту" value="${esc(current.title)}" autofocus></label><label class="field span-2">Ожидаемый результат<textarea name="description" maxlength="10000" placeholder="Что должно быть сделано и по каким критериям будет принято">${esc(current.description)}</textarea></label><label class="field">Ответственный *<select name="owner">${selectOptions(Object.fromEntries(data.people.map(p=>[p.id,p.name])),current.owner)}</select></label><label class="field">Направление *<select name="sector">${selectOptions(SECTORS,current.sector)}</select></label><label class="field">Сложность *<select name="complexity">${selectOptions(Object.fromEntries(Object.entries(LEVELS).map(([k,v])=>[k,`${v} · ${COMPLEXITY[k]} балл.`])),current.complexity)}</select></label><label class="field">Срок исполнения *<input class="input" name="due" type="date" required min="2000-01-01" max="2100-12-31" value="${esc(current.due)}"></label><label class="field">Приоритет<select name="priority">${selectOptions(PRIORITY,current.priority)}</select><small>Приоритет помогает планированию и не меняет вес KPI.</small></label><label class="field">Этапы / чек-лист<textarea name="checklist" maxlength="5000" placeholder="Один пункт на строку">${esc(current.checklist.map(c=>c.label).join('\n'))}</textarea></label><div class="field span-2">Зависит от поручений<small>Принятие результата возможно после завершения выбранных поручений.</small><div class="dependency-list">${data.tasks.filter(x=>x.id!==t?.id).map(x=>`<label class="dependency-option"><input type="checkbox" name="dependencies" value="${esc(x.id)}" ${current.dependencies.includes(x.id)?'checked':''}><span>${esc(x.id)} · ${esc(x.title)}</span></label>`).join('')||'<span class="muted">Других поручений пока нет</span>'}</div></div></div><div id="form-error" class="error" role="alert"></div></div><div class="dialog-actions"><span class="muted" style="font-size:10px">* Обязательные поля</span><div>${btn('Отмена','close-dialog')}<button type="submit" class="btn primary">${icon('check')}${t?'Сохранить изменения':'Создать поручение'}</button></div></div></form>`);
}
function showTask(id){const t=data.tasks.find(t=>t.id===id);if(!t)return;const p=person(t.owner);const approved=t.status==='Approved';
 openDialog(dialogHeader(esc(t.id),approved?'Результат принят руководителем':'Карточка поручения')+`<div class="dialog-body"><div class="detail-tags">${statusPill(t)}${sectorPill(t.sector)}${isOverdue(t)?'<span class="pill late">Просрочено</span>':''}<span class="pill ${t.priority.toLowerCase()}">${PRIORITY[t.priority]} приоритет</span></div><h3 class="detail-title">${esc(t.title)}</h3><p class="detail-description">${esc(t.description)||'Описание не указано.'}</p><div class="detail-meta"><div><small>Ответственный</small><strong>${esc(p.name)}</strong></div><div><small>Срок исполнения</small><strong>${dateLabel(t.due,true)}</strong></div><div><small>Сложность</small><strong>${LEVELS[t.complexity]} · ${COMPLEXITY[t.complexity]} балл.</strong></div></div>${t.dependencies.length?`<h4 class="section-label">Предварительные поручения</h4>${t.dependencies.map(d=>{const dep=data.tasks.find(x=>x.id===d);return `<div style="display:flex;gap:8px;margin:8px 0;align-items:center">${statusPill(dep)}<button class="task-title-btn" data-task="${esc(d)}">${esc(dep.title)}</button></div>`;}).join('')}`:''}<h4 class="section-label">Чек-лист <small id="check-count">${t.checklist.filter(c=>c.done).length} / ${t.checklist.length}</small></h4>${t.checklist.map((c,i)=>`<label class="checklist-item ${c.done?'done':''}"><input type="checkbox" data-check="${i}" data-id="${esc(id)}" ${c.done?'checked':''} ${approved?'disabled':''}><span>${esc(c.label)}</span></label>`).join('')||'<p class="muted" style="font-size:11px">Добавьте этапы через редактирование поручения.</p>'}${approved?`<h4 class="section-label">Принятый результат <span class="quality-stars" aria-label="Качество: ${t.quality} из 5">${'★'.repeat(t.quality)}${'☆'.repeat(5-t.quality)}</span></h4><div class="evidence">${esc(t.evidence)}</div><p class="approval-note">Дата выполнения: ${dateLabel(t.completedAt,true)} · ${t.completedAt<=t.due?'Выполнено в срок':'Выполнено после срока'}. Включено в KPI за ${monthLabel(t.due.slice(0,7))}.</p>`:`<form id="progress-form" data-id="${esc(id)}"><h4 class="section-label">Исполнение поручения</h4><div class="form-grid"><label class="field">Статус<select name="status">${selectOptions(Object.fromEntries(STATUSES.filter(s=>s!=='Approved').map(s=>[s,STATUS[s]])),t.status)}</select></label><label class="field">Прогресс<div class="range-row"><input type="range" name="progress" min="0" max="100" step="5" value="${t.progress}" aria-label="Прогресс"><output>${t.progress}%</output></div></label><label class="field span-2">Отчёт об исполнении / подтверждение результата<textarea name="evidence" maxlength="10000" placeholder="Опишите результат, укажите реквизиты документа или ссылку на материалы">${esc(t.evidence)}</textarea><small>В демоверсии используются текстовые отчёты и ссылки; файлы не загружаются.</small></label></div><div id="progress-error" class="error" role="alert"></div><div style="margin-top:13px"><button type="submit" class="btn primary small">${icon('save')}Сохранить ход исполнения</button></div></form>`}<h4 class="section-label">История и комментарии <small>${t.comments.length}</small></h4><div>${t.comments.slice(-10).map(c=>`<div class="update-row"><span class="avatar" style="width:27px;height:27px;font-size:9px">ЗД</span><div><p>${esc(c.text)}</p><small>${formatTimestamp(c.at)}</small></div></div>`).join('')||'<p style="font-size:11px;color:var(--muted)">Здесь появятся комментарии и изменения по поручению.</p>'}</div><form id="comment-form" class="comment-form" data-id="${esc(id)}"><textarea name="comment" required maxlength="3000" aria-label="Новый комментарий" placeholder="Добавить комментарий…"></textarea><button type="submit" class="btn" aria-label="Отправить комментарий">${icon('send')}<span>Отправить</span></button></form></div><div class="dialog-actions">${approved?btn('Вернуть в работу','reopen-task','edit','',`data-id="${esc(id)}"`):btn('Редактировать','edit-task','edit','',`data-id="${esc(id)}"`)}<div>${btn('Закрыть','close-dialog')}${t.status==='In review'?btn('Принять результат','approve-task','check','primary',`data-id="${esc(id)}"`):''}</div></div>`);
}
function formatTimestamp(at){const d=new Date(at);return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat('ru-RU',{timeZone:'Asia/Tashkent',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(d)+' · Ташкент';}
function addHistory(t,text){t.comments.push({text,at:new Date().toISOString()});}
function approveTask(id){const t=data.tasks.find(t=>t.id===id);const problem=approvalError(t);if(problem){toast(problem);return;}openDialog(dialogHeader('Принять результат',esc(t.id)+' · '+esc(person(t.owner).name))+`<form id="approval-form" data-id="${esc(id)}"><div class="dialog-body"><h3 style="font-size:16px;line-height:1.7;margin-top:0">${esc(t.title)}</h3><div class="evidence">${esc(t.evidence)}</div><div class="form-grid" style="margin-top:22px"><label class="field">Дата фактического выполнения *<input class="input" name="completedAt" type="date" value="${TODAY}" max="${TODAY}" min="2000-01-01" required><small>Используется для оценки соблюдения срока.</small></label><label class="field">Оценка качества *<select name="quality"><option value="5">5 — Полностью соответствует ожиданиям</option><option value="4">4 — Незначительные замечания</option><option value="3">3 — Приемлемый результат</option><option value="2">2 — Существенные замечания</option><option value="1">1 — Низкое качество</option></select></label></div><div class="callout">В KPI за ${monthLabel(t.due.slice(0,7))} будут учтены ${COMPLEXITY[t.complexity]} балл. сложности. Дата выполнения, а не дата принятия, определяет соблюдение срока.</div><div id="approval-error" class="error" role="alert"></div></div><div class="dialog-actions">${btn('Назад к поручению','back-task','','',`data-id="${esc(id)}"`)}<button type="submit" class="btn primary">${icon('check')}Подтвердить принятие</button></div></form>`);}
function approvalError(t){if(!t.evidence.trim())return 'Добавьте отчёт об исполнении перед принятием.';if(t.checklist.some(c=>!c.done))return 'Сначала отметьте все пункты чек-листа.';if(t.dependencies.some(id=>data.tasks.find(x=>x.id===id)?.status!=='Approved'))return 'Сначала примите результаты предварительных поручений.';return '';}
function personDialog(id){const p=person(id)||{id:'',name:'',role:'',sector:'Textile'};openDialog(dialogHeader(p.id?'Редактировать сотрудника':'Новый сотрудник','Добавьте участника в рабочее пространство')+`<form id="person-form" data-id="${esc(p.id)}"><div class="dialog-body"><div class="form-grid"><label class="field span-2">Имя и фамилия *<input class="input" name="name" value="${esc(p.name)}" maxlength="100" required autofocus></label><label class="field">Должность *<input class="input" name="role" value="${esc(p.role)}" maxlength="150" required></label><label class="field">Направление *<select name="sector">${selectOptions(SECTORS,p.sector)}</select></label></div><div id="person-error" class="error" role="alert"></div></div><div class="dialog-actions"><span class="muted" style="font-size:10px">Демо: приглашения не отправляются</span><div>${btn('Отмена','close-dialog')}<button type="submit" class="btn primary">${icon('check')}Сохранить</button></div></div></form>`);}
function showMethodology(){openDialog(dialogHeader('Как рассчитывается KPI','Прозрачная методика для обсуждения')+`<div class="dialog-body help-copy"><p>Каждое поручение попадает в месяц своего срока исполнения. В отчёт включаются все назначенные поручения этого месяца, включая незавершённые. Результаты учитываются только в статусе «Принято».</p><h3>1. Вес сложности</h3><p>Простая задача — 1 балл, стандартная — 2, сложная — 3, стратегическая — 5. Срочность и процент прогресса не увеличивают баллы.</p><h3>2. Три показателя, каждый от 0 до 100%</h3><p><strong>Выполнение:</strong> сумма баллов принятых поручений / сумма баллов всех поручений месяца.<br><strong>Сроки:</strong> сумма баллов принятых и выполненных не позднее срока поручений / сумма всех баллов месяца.<br><strong>Качество:</strong> сумма (баллы принятого поручения × оценка качества / 5) / сумма всех баллов месяца.</p><h3>3. Итог</h3><p>KPI = выполнение × ${data.weights.completion}% + сроки × ${data.weights.timeliness}% + качество × ${data.weights.quality}%. Округление применяется только при отображении. Сотрудники без поручений получают «—» и не влияют на среднее команды.</p><div class="callout">Пример при весах 50 / 30 / 20: назначено 10 баллов; принято 8, из них в срок 6; все принятые результаты оценены на 4/5. Выполнение — 80%, сроки — 60%, качество — 64%. Итоговый KPI = 70,8 (на экране 71).</div><h3>Как читать отчёт</h3><p>Текущий месяц — предварительный. Изменение сроков, сложности, оценок и весов пересчитывает прошлые периоды: фиксации закрытого месяца в демо нет. Дата выполнения подтверждается руководителем при принятии результата.</p><p>Эта методика — предложение для демоверсии, а не утверждённая система оценки Агентства. Для принятия кадровых решений необходимо учитывать контекст работы и согласовать критерии.</p></div><div class="dialog-actions">${btn('Настроить веса','configure-weights','settings')} ${btn('Понятно','close-dialog','check','primary')}</div>`);}
function helpDialog(){openDialog(dialogHeader('Добро пожаловать в Taskmanag','Демонстрационный портал управления поручениями')+`<div class="dialog-body help-copy"><p>Рабочее место заместителя директора Агентства по развитию лёгкой промышленности Республики Узбекистан.</p><ol><li><strong>Создайте поручение.</strong> Назначьте ответственного, срок, сложность, чек-лист и зависимости.</li><li><strong>Следите за исполнением.</strong> Откройте карточку, обновите прогресс и добавьте комментарий или отчёт.</li><li><strong>Примите результат.</strong> Переведите задачу на проверку, завершите чек-лист и укажите оценку качества и дату выполнения.</li><li><strong>Посмотрите KPI.</strong> Выберите месяц и скачайте отчёт. Для полного примера откройте предыдущий месяц.</li></ol><h3>Что доступно в демо</h3><p>Единое рабочее место руководителя, вымышленные сотрудники, локальные изменения в браузере, резервные копии JSON и отчёты CSV. Интерфейс работает без подключения к интернету.</p><h3>Что потребуется для рабочей версии</h3><p>Вход пользователей, разграничение прав, общая база данных, защищённые вложения, уведомления, журнал действий и фиксация месячных результатов. В демо действия руководителя и исполнителя выполняются из одной карточки.</p></div><div class="dialog-actions">${btn('Методика KPI','methodology','chart')}${btn('Начать работу','close-dialog','arrow','primary')}</div>`);}
function confirmDialog(title,copy,action,label,extra=''){openDialog(dialogHeader(title)+`<div class="dialog-body help-copy">${copy}</div><div class="dialog-actions">${btn('Отмена','close-dialog')}${btn(label,action,'','danger',extra)}</div>`);}
function download(content,type,name){const blob=new Blob([content],{type});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),2000);}
function exportKpi(){const rows=[['Отчёт Taskmanag',monthLabel(state.month)],['Методика',`Выполнение ${data.weights.completion}%; сроки ${data.weights.timeliness}%; качество ${data.weights.quality}%`],['Статус',state.month>=MONTH?'Предварительный':'По текущим данным'],['Сотрудник','Направление','Поручений','Принято','Назначено баллов','Принято баллов','Выполнение %','Сроки %','Качество %','KPI / 100']];for(const p of data.people){const s=kpi(data.tasks,p.id,state.month,data.weights);rows.push([p.name,SECTORS[p.sector],s.assigned,s.approved,s.total,s.earned,...[s.completion,s.timeliness,s.quality,s.score].map(n=>n==null?'':n.toFixed(2).replace('.',','))]);}download('\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8',`Taskmanag-KPI-${state.month}.csv`);toast('Отчёт KPI скачан.');}
function navigate(page){state.page=page;state.mobile=false;render();window.scrollTo({top:0});}
function goTasks(owner='all',status='all'){state.owner=owner;state.status=status;state.query='';state.sector='all';navigate('tasks');}
let pendingImport=null;
document.addEventListener('click',event=>{const target=event.target.closest('button,[data-action]');if(!target)return;
 if(target.dataset.page){navigate(target.dataset.page);return;}
 if(target.dataset.task){showTask(target.dataset.task);return;}
 if(target.dataset.filter){state.status=target.dataset.filter;render();return;}
 if(target.dataset.view){state.view=target.dataset.view;render();return;}
 const id=target.dataset.id;
 switch(target.dataset.action){
 case 'new-task':newTask();break;case 'edit-task':newTask(id);break;case 'back-task':showTask(id);break;case 'close-dialog':closeDialog();break;
 case 'new-person':personDialog();break;case 'edit-person':personDialog(id);break;case 'person-tasks':goTasks(id);break;case 'all-tasks':goTasks();break;case 'review':goTasks('all','In review');break;
 case 'go-kpi':navigate('kpi');break;case 'menu':state.mobile=!state.mobile;render();break;case 'close-menu':state.mobile=false;render();break;
 case 'month-prev':case 'month-next':{const next=monthShift(state.month,target.dataset.action==='month-prev'?-1:1);if(next>='2000-01'&&next<='2100-12'){state.month=next;render();}break;}
 case 'reset-filters':state.query='';state.sector='all';state.owner='all';state.status='all';render();break;
 case 'approve-task':approveTask(id);break;
 case 'reopen-task':confirmDialog('Вернуть поручение в работу?','<p>Принятые баллы будут исключены из KPI, пока результат не будет принят повторно. Комментарии и отчёт сохранятся.</p>','confirm-reopen','Вернуть в работу',`data-id="${esc(id)}"`);break;
 case 'confirm-reopen':{const t=data.tasks.find(t=>t.id===id);t.status='In progress';t.completedAt=null;t.progress=90;addHistory(t,'Поручение возвращено руководителем в работу.');save();render();showTask(id);toast('Поручение возвращено в работу. KPI пересчитан.');break;}
 case 'methodology':showMethodology();break;case 'help':helpDialog();break;case 'configure-weights':closeDialog();navigate('settings');break;
 case 'default-weights':for(const k of Object.keys(DEFAULT_WEIGHTS))$(`[name="${k}"]`,$('#weights-form')).value=DEFAULT_WEIGHTS[k];toast('Значения восстановлены. Нажмите «Сохранить методику».');break;
 case 'export-kpi':exportKpi();break;
 case 'export-backup':download(JSON.stringify(data,null,2),'application/json',`Taskmanag-backup-${TODAY}.json`);toast('Резервная копия скачана.');break;
 case 'import-backup':$('#import-file').value='';$('#import-file').click();break;
 case 'confirm-import':if(pendingImport){data=pendingImport;pendingImport=null;save();closeDialog();render();toast('Данные восстановлены из резервной копии.');}break;
 case 'reset-data':confirmDialog('Вернуть демонстрационные данные?','<p>Ваши локальные изменения будут заменены исходными примерами. Сначала скачайте резервную копию, если хотите сохранить свои поручения.</p>','confirm-reset','Вернуть примеры');break;
 case 'confirm-reset':data=seedData();save();closeDialog();state.month=MONTH;render();toast('Демонстрационные данные восстановлены.');break;
 }
});
document.addEventListener('input',event=>{if(event.target.id==='task-search'){state.query=event.target.value;$('#task-results').innerHTML=taskResults();}if(event.target.name==='progress'&&event.target.type==='range')event.target.nextElementSibling.textContent=event.target.value+'%';});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='month'&&/^\d{4}-\d{2}$/.test(el.value)&&el.value>='2000-01'&&el.value<='2100-12'){state.month=el.value;render();}
 if(el.id==='sector-filter'||el.id==='owner-filter'){state[el.id==='sector-filter'?'sector':'owner']=el.value;$('#task-results').innerHTML=taskResults();}
 if(el.dataset.check!==undefined){const t=data.tasks.find(t=>t.id===el.dataset.id);if(t.status==='Approved')return;t.checklist[Number(el.dataset.check)].done=el.checked;addHistory(t,`${el.checked?'Выполнен':'Возвращён'} пункт: ${t.checklist[Number(el.dataset.check)].label}`);save();el.closest('label').classList.toggle('done',el.checked);$('#check-count').textContent=t.checklist.filter(c=>c.done).length+' / '+t.checklist.length;}
 if(el.id==='import-file'&&el.files[0]){try{if(el.files[0].size>5*1024*1024)throw new Error('Файл слишком большой. Максимум — 5 МБ.');pendingImport=validateData(JSON.parse(await el.files[0].text()));confirmDialog('Заменить данные резервной копией?',`<p>Будут загружены ${pendingImport.people.length} сотрудников и ${pendingImport.tasks.length} поручений. Текущие изменения будут заменены. При необходимости сначала скачайте текущую резервную копию.</p>`,'confirm-import','Восстановить данные');}catch(err){pendingImport=null;toast('Не удалось загрузить файл. '+(err.message.startsWith('Файл')?err.message:'Проверьте формат резервной копии Taskmanag.'));}}
});
document.addEventListener('submit',event=>{const form=event.target;if(!['task-form','person-form','progress-form','comment-form','approval-form','weights-form'].includes(form.id))return;event.preventDefault();const f=new FormData(form),id=form.dataset.id;
 if(form.id==='task-form'){
  if(!String(f.get('title')).trim()){$('#form-error').textContent='Укажите название поручения.';return;}
  const labels=String(f.get('checklist')).split('\n').map(s=>s.trim()).filter(Boolean);if(labels.some(s=>s.length>500)){$('#form-error').textContent='Пункт чек-листа должен быть не длиннее 500 символов.';return;}
  const old=data.tasks.find(t=>t.id===id);const number=Math.max(1000,...data.tasks.map(t=>Number(t.id.replace('TM-',''))||0))+1;
  const task={...(old||{id:'TM-'+number,status:'Not started',progress:0,quality:5,completedAt:null,evidence:'',comments:[]}),title:String(f.get('title')).trim(),description:String(f.get('description')).trim(),owner:f.get('owner'),sector:f.get('sector'),complexity:f.get('complexity'),priority:f.get('priority'),due:f.get('due'),checklist:labels.map(label=>({label,done:old?.checklist.find(c=>c.label===label)?.done||false})),dependencies:f.getAll('dependencies')};
  const candidate={...data,tasks:old?data.tasks.map(t=>t.id===id?task:t):[...data.tasks,task]};try{validateData(candidate);}catch(err){$('#form-error').textContent=err.message.includes('cycle')?'Обнаружена циклическая зависимость. Измените предварительные поручения.':'Проверьте поля и зависимости поручения.';return;}
  addHistory(task,old?'Параметры поручения обновлены руководителем.':'Поручение создано и назначено ответственному.');data=candidate;save();render();showTask(task.id);toast(old?'Изменения сохранены.':'Поручение создано.');
 }
 if(form.id==='person-form'){
  const name=String(f.get('name')).trim(),role=String(f.get('role')).trim();if(!name||!role){$('#person-error').textContent='Укажите имя и должность сотрудника.';return;}
  if(!id&&data.people.length>=200){$('#person-error').textContent='В демоверсии поддерживается до 200 сотрудников.';return;}
  const p={id:id||'p-'+Date.now().toString(36),name,role,sector:f.get('sector')};if(id)data.people=data.people.map(x=>x.id===id?p:x);else data.people.push(p);save();closeDialog();render();toast('Сотрудник сохранён.');
 }
 if(form.id==='progress-form'){
  const t=data.tasks.find(t=>t.id===id);let progress=Number(f.get('progress')),status=f.get('status');if(status==='In review'&&!String(f.get('evidence')).trim()){$('#progress-error').textContent='Перед отправкой на проверку добавьте отчёт об исполнении.';return;}
  if(status==='Not started')progress=0;if(status==='In review')progress=100;t.status=status;t.progress=progress;t.evidence=String(f.get('evidence')).trim();addHistory(t,`Ход исполнения обновлён: ${STATUS[status]}, ${progress}%.`);save();render();showTask(id);toast(status==='In review'?'Поручение направлено на проверку.':'Ход исполнения сохранён.');
 }
 if(form.id==='comment-form'){const text=String(f.get('comment')).trim();if(!text){form.comment.setCustomValidity('Введите текст комментария.');form.comment.reportValidity();form.comment.oninput=()=>form.comment.setCustomValidity('');return;}const t=data.tasks.find(t=>t.id===id);addHistory(t,text);save();const scroll=$('#dialog').scrollTop;showTask(id);$('#dialog').scrollTop=scroll;toast('Комментарий добавлен.');}
 if(form.id==='approval-form'){
  const t=data.tasks.find(t=>t.id===id);const completedAt=f.get('completedAt'),quality=Number(f.get('quality'));const problem=approvalError(t);if(problem||t.status!=='In review'||!validDate(completedAt)||completedAt>TODAY||!Number.isInteger(quality)||quality<1||quality>5){$('#approval-error').textContent=problem||'Проверьте дату выполнения и оценку качества.';return;}
  t.status='Approved';t.progress=100;t.completedAt=completedAt;t.quality=quality;addHistory(t,`Результат принят руководителем. Качество: ${quality}/5. Дата выполнения: ${dateLabel(completedAt,true)}.`);save();render();showTask(id);toast('Результат принят. KPI автоматически пересчитан.');
 }
 if(form.id==='weights-form'){const weights=Object.fromEntries(Object.keys(DEFAULT_WEIGHTS).map(k=>[k,Number(f.get(k))]));if(!validWeights(weights)){$('#weights-error').textContent='Сумма весов должна равняться 100%.';return;}data.weights=weights;save();render();toast('Методика сохранена. Все отчёты пересчитаны.');}
});
render();
